/// https://github.com/ethereum/consensus-specs/blob/v1.1.5/specs/merge/beacon-chain.md#process_execution_payload
pub fn partially_verify_execution_payload<E: EthSpec, Payload: AbstractExecPayload<E>>(
    state: &BeaconState<E>,
    block_slot: Slot,
    body: BeaconBlockBodyRef<E, Payload>,
    spec: &ChainSpec,
) -> Result<(), BlockProcessingError> {
    let payload = body.execution_payload()?;
    if is_merge_transition_complete(state) {
        block_verify!(
            payload.parent_hash() == state.latest_execution_payload_header()?.block_hash(),
            BlockProcessingError::ExecutionHashChainIncontiguous {
                expected: state.latest_execution_payload_header()?.block_hash(),
                found: payload.parent_hash(),
            }
        );
    }
    block_verify!(
        payload.prev_randao() == *state.get_randao_mix(state.current_epoch())?,
        BlockProcessingError::ExecutionRandaoMismatch {
            expected: *state.get_randao_mix(state.current_epoch())?,
            found: payload.prev_randao(),
        }
    );

    let timestamp = compute_timestamp_at_slot(state, block_slot, spec)?;
    block_verify!(
        payload.timestamp() == timestamp,
        BlockProcessingError::ExecutionInvalidTimestamp {
            expected: timestamp,
            found: payload.timestamp(),
        }
    );

    if let Ok(blob_commitments) = body.blob_kzg_commitments() {
        // Verify commitments are under the limit.
        let max_blobs_per_block =
            spec.max_blobs_per_block(block_slot.epoch(E::slots_per_epoch())) as usize;
        block_verify!(
            blob_commitments.len() <= max_blobs_per_block,
            BlockProcessingError::ExecutionInvalidBlobsLen {
                max: max_blobs_per_block,
                actual: blob_commitments.len(),
            }
        );
    }

    Ok(())
}

/// Return the value of `MAX_BLOBS_PER_BLOCK` for the given `epoch`.
/// NOTE: this function is *technically* not spec compliant, but
/// I'm told this is what the other clients are doing for `devnet-0`..
pub fn max_blobs_per_block(&self, epoch: Epoch) -> u64 {
    match self.fulu_fork_epoch {
        Some(fulu_epoch) if epoch >= fulu_epoch => self
            .blob_schedule
            .max_blobs_for_epoch(epoch)
            .unwrap_or(self.max_blobs_per_block_electra),
        _ => match self.electra_fork_epoch {
            Some(electra_epoch) if epoch >= electra_epoch => self.max_blobs_per_block_electra,
            _ => self.max_blobs_per_block,
        },
    }
}

/// Return the blob parameters at a given epoch.
fn get_blob_parameters(&self, epoch: Epoch) -> Option<BlobParameters> {
    match self.fulu_fork_epoch {
        Some(fulu_epoch) if epoch >= fulu_epoch => self
            .blob_schedule
            .blob_parameters_for_epoch(epoch)
            .or_else(|| {
                Some(BlobParameters {
                    epoch: self
                        .electra_fork_epoch
                        .expect("electra fork epoch must be set if fulu epoch is set"),
                    max_blobs_per_block: self.max_blobs_per_block_electra,
                })
            }),
        _ => None,
    }
}

